import React, { useState, useEffect, useCallback } from "react";
import { BrowserRouter, Routes, Route } from "react-router-dom";
import "./styles/global.css";

import Nav from "./components/Nav";
import MobileDrawer from "./components/MobileDrawer";
import Footer from "./components/Footer";
import CartDrawer from "./components/CartDrawer";

import Home from "./pages/Home";
// import About from "./pages/About";
// import ProductDetail from "./pages/ProductDetail";

import { COLORS, FONT_BODY, THEME_MODES, THEME_STORAGE_KEY } from "./constants/theme";

const DRAWER_WIDTH = 280;

const getInitialThemeMode = () => {
  if (typeof window === "undefined") return THEME_MODES.LIGHT;

  const storedTheme = window.localStorage.getItem(THEME_STORAGE_KEY);
  if (storedTheme === THEME_MODES.LIGHT || storedTheme === THEME_MODES.DARK) {
    return storedTheme;
  }

  const mediaQuery =
    typeof window.matchMedia === "function"
      ? window.matchMedia("(prefers-color-scheme: dark)")
      : null;

  return mediaQuery?.matches ? THEME_MODES.DARK : THEME_MODES.LIGHT;
};

export default function App() {
  const [themeMode, setThemeMode] = useState(getInitialThemeMode);
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const [cartOpen, setCartOpen] = useState(false);
  const [cart, setCart] = useState([]);
  const [filter, setFilter] = useState("All");
  const [checkedOut, setCheckedOut] = useState(false);
  const [bump, setBump] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 40);
    window.addEventListener("scroll", onScroll);
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  useEffect(() => {
    document.documentElement.setAttribute("data-theme", themeMode);
    window.localStorage.setItem(THEME_STORAGE_KEY, themeMode);
  }, [themeMode]);

  // lock background scroll while the drawer is open
  useEffect(() => {
    document.body.style.overflow = menuOpen ? "hidden" : "";
    return () => {
      document.body.style.overflow = "";
    };
  }, [menuOpen]);

  const addToCart = useCallback((product) => {
    setCart((prev) => {
      const found = prev.find((i) => i.id === product.id);
      if (found) {
        return prev.map((i) => (i.id === product.id ? { ...i, qty: i.qty + 1 } : i));
      }
      return [...prev, { ...product, qty: 1 }];
    });
    setBump(true);
    setTimeout(() => setBump(false), 400);
  }, []);

  const updateQty = (id, delta) => {
    setCart((prev) =>
      prev
        .map((i) => (i.id === id ? { ...i, qty: Math.max(0, i.qty + delta) } : i))
        .filter((i) => i.qty > 0)
    );
  };

  const removeItem = (id) => setCart((prev) => prev.filter((i) => i.id !== id));

  const cartCount = cart.reduce((sum, i) => sum + i.qty, 0);
  const subtotal = cart.reduce((sum, i) => sum + i.qty * i.price, 0);

  const scrollTo = (id) => {
    setMenuOpen(false);
    const el = document.getElementById(id);
    if (el) el.scrollIntoView({ behavior: "smooth", block: "start" });
  };

  const toggleTheme = useCallback(() => {
    setThemeMode((current) =>
      current === THEME_MODES.DARK ? THEME_MODES.LIGHT : THEME_MODES.DARK
    );
  }, []);

  return (
    <BrowserRouter>
      <div
        style={{
          fontFamily: FONT_BODY,
          background: COLORS.surfaceBase,
          color: COLORS.text,
          position: "relative",
          minHeight: "100vh",
          overflowX: "hidden", // hides the strip of page that slides past the right edge
        }}
      >
        {/* Drawer: fixed behind everything (zIndex 1), revealed as the page slides away from it */}
        <MobileDrawer menuOpen={menuOpen} setMenuOpen={setMenuOpen} scrollTo={scrollTo} width={DRAWER_WIDTH} />

        {/* Header: rendered as a sibling here, NOT inside the sliding wrapper below.
            It stays position:fixed to the real viewport and keeps its own zIndex
            (50, set inside Nav.jsx) above both the drawer and the sliding page —
            so the menu/close toggle is always exactly where you tapped it,
            regardless of whether the drawer is open. */}
        <Nav
          scrolled={scrolled}
          menuOpen={menuOpen}
          setMenuOpen={setMenuOpen}
          cartOpen={cartOpen}
          setCartOpen={setCartOpen}
          cartCount={cartCount}
          bump={bump}
          scrollTo={scrollTo}
          setFilter={setFilter}
          themeMode={themeMode}
          toggleTheme={toggleTheme}
        />

        {/* Only the page body slides — this is the container that gets the transform */}
        <div
          className="nyasa-root"
          style={{
            position: "relative",
            zIndex: 2,
            background: COLORS.surfaceBase,
            minHeight: "100vh",
            transform: menuOpen ? `translateX(${DRAWER_WIDTH}px)` : "translateX(0)",
            transition: "transform 0.3s ease",
          }}
        >
          {/* Tap-anywhere-on-the-page-to-close overlay, only while open.
              zIndex 40: above the page content (2), below the header (50), so it
              never blocks the header's own buttons. */}
          {menuOpen && (
            <div
              className="md:hidden"
              onClick={() => setMenuOpen(false)}
              aria-hidden="true"
              style={{
                position: "fixed",
                inset: 0,
                zIndex: 40,
                background: "transparent",
              }}
            />
          )}

          <Routes>
            <Route
              path="/"
              element={
                <Home filter={filter} setFilter={setFilter} addToCart={addToCart} scrollTo={scrollTo} />
              }
            />
            {/* <Route path="/about" element={<About />} /> */}
            {/* <Route path="/product/:id" element={<ProductDetail addToCart={addToCart} />} /> */}
          </Routes>

          <Footer setFilter={setFilter} scrollTo={scrollTo} />
        </div>

        {/* Cart drawer also kept outside the sliding wrapper so it isn't affected by menuOpen */}
        <CartDrawer
          cartOpen={cartOpen}
          setCartOpen={setCartOpen}
          cart={cart}
          checkedOut={checkedOut}
          setCheckedOut={setCheckedOut}
          updateQty={updateQty}
          removeItem={removeItem}
          subtotal={subtotal}
        />
      </div>
    </BrowserRouter>
  );
}
